int lengthOfLongestSubstring(char *s) {
  int offset[128];
  int max_len = 0;
  int len = 0;

  memset(offset, 0xff, sizeof(offset));
  for (int i = 0; i < strlen(s); i++) {
    if (offset[(int)*(s + i)] == -1) {
      len++;
    } else {
      if (i - offset[(int)*(s + i)] > len) {
        len++;
      } else {
        len = i - offset[(int)*(s + i)];
      }
    }
    if (len > max_len) {
      max_len = len;
    }
    offset[(int)*(s + i)] = i;
  }

  return max_len;
}

class Solution {
public:
  int lengthOfLongestSubstring(string s) {
    unordered_map<char, int> last;
    int start = 0, result = 0;
    for (int i = 0; i < (int)s.size(); i++) {
      if (last.count(s[i]) && last[s[i]] >= start) {
        start = last[s[i]] + 1;
      }
      last[s[i]] = i;
      result = max(result, i - start + 1);
    }
    return result;
  }
};

func lengthOfLongestSubstring(s string) int {
	n := len(s)
	if n < 2 {
		return n
	}
	max := 0
	for i := 0; i < n; i++ {
		mp := make(map[uint8]int)
		mp[s[i]] = 1
		for j := i + 1; j < n; j++ {
			if _, ok := mp[s[j]]; !ok {
				mp[s[j]] = 1
			} else {
				break
			}
		}
		if max < len(mp) {
			max = len(mp)
		}
	}
	return max
}

class Solution {
  public int lengthOfLongestSubstring(String s) {
    if (s == null || s.length() == 0) {
      return 0;
    }
    int result = 0;
    int start = 0;
    int length = 0;
    HashMap<Character, Integer> indexMap = new HashMap<>();
    for (int i = 0; i < s.length(); i++) {
      if (indexMap.containsKey(s.charAt(i)) && indexMap.get(s.charAt(i)) >= start) {
        start = indexMap.get(s.charAt(i)) + 1;
      }
      length = i - start + 1;
      indexMap.put(s.charAt(i), i);
      result = Math.max(length, result);
    }
    return result;
  }
}

class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        last = {}
        start = 0
        result = 0
        for i, ch in enumerate(s):
            if ch in last and last[ch] >= start:
                start = last[ch] + 1
            last[ch] = i
            result = max(result, i - start + 1)
        return result

use std::collections::HashMap;
impl Solution {
  pub fn length_of_longest_substring(s: String) -> i32 {
    let chars: Vec<char> = s.chars().collect();
    let mut last: HashMap<char, usize> = HashMap::new();
    let mut start = 0usize;
    let mut result = 0usize;
    for i in 0..chars.len() {
      if let Some(&prev) = last.get(&chars[i]) {
        if prev >= start {
          start = prev + 1;
        }
      }
      last.insert(chars[i], i);
      if i - start + 1 > result {
        result = i - start + 1;
      }
    }
    result as i32
  }
}

const lengthOfLongestSubstring = (s: string): number => {
  const last = new Map<string, number>();
  let start = 0;
  let result = 0;

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (last.has(ch) && (last.get(ch) as number) >= start) {
      start = (last.get(ch) as number) + 1;
    }
    last.set(ch, i);
    result = Math.max(result, i - start + 1);
  }

  return result;
};
